theme.css:
/* ==== INTERFACE ====
   token  --bg #F5F7FA            页面基底｜冷灰底色
   token  --text #182230          主正文｜高对比冷深青黑
   token  --muted #5D6B82         次级说明、边框与刻度线｜冷蓝灰
   token  --ens-primary #1D4ED8   主模型、强分类器、主流向
   token  --ens-accent #D9480F    高亮残差、误分类样本、当前激活迭代
   token  --ens-sub #0F766E       基学习器分支、独立特征空间
   token  --fs-h1 34              页标题字号
   token  --fs-h2 22              区块标题字号
   token  --fs-lead 19            导语字号
   token  --fs-body 18            正文字号
   token  --fs-sec 16             次级正文字号
   token  --fs-label 15           控件与图例标签字号
   token  --fs-tick 13            坐标与刻度字号
   版心   1488×844                #stage 已含 padding
   版式   .focus                  标题后主内容区
   ==== /INTERFACE ==== */

:root {
  --bg: #F5F7FA;
  --text: #182230;
  --muted: #5D6B82;
  --ens-primary: #1D4ED8;
  --ens-accent: #D9480F;
  --ens-sub: #0F766E;
  --focus: #D9480F;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --pad-x: 56px;
  --pad-y: 28px;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.45;
}

.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

svg .bar, svg .cell, svg .box { width:auto; height:auto; }
